<script setup lang="ts">import {computed,ref} from 'vue';import {useRouter} from 'vue-router';import {ArrowRight} from 'lucide-vue-next';import {useResearchData} from '../hooks/useResearch';import {useAuth} from '../stores/auth';import {useAction} from '../hooks/useAction';import {createRun} from '../api/runs';import CohortSelector from '../components/CohortSelector.vue';import Notice from '../components/common/Notice.vue';const s=useResearchData(),auth=useAuth(),a=useAction(),router=useRouter(),name=ref(''),aid=ref(0),bid=ref(0),confidence=ref(.95);const ca=computed(()=>aid.value||s.cohorts[0]?.id||0),cb=computed(()=>bid.value||s.cohorts[1]?.id||0);function submit(){a.execute(async()=>{const r=await createRun({name:name.value,cohort_a_id:ca.value,cohort_b_id:cb.value,confidence:confidence.value});router.push('/results?run='+r.id)})}</script><template><div class="page"><div class="page-title"><div><p class="eyebrow">COMPARISON PROTOCOL / 03</p><h1>比较配置<span>先确认删失含义，再比较两条耐久曲线。</span></h1></div></div><Notice :message="s.error||a.error.value" @retry="s.refresh"/><div class="editor-grid"><form class="research-form" @submit.prevent="submit"><div class="form-heading"><span>01</span><h2>定义这次研究</h2></div><label>研究名称<input aria-label="研究名称" v-model="name" minlength="2" maxlength="120" placeholder="例如：秋季两批封装耐久比较" required :disabled="auth.user?.role==='viewer'"/></label><CohortSelector :cohorts="s.cohorts" :model-value="ca" label="对照工艺批次" @update:model-value="aid=$event"/><CohortSelector :cohorts="s.cohorts" :model-value="cb" label="比较工艺批次" @update:model-value="bid=$event"/><div class="form-heading second"><span>02</span><h2>固定分析口径</h2></div><label>逐点置信水平<select v-model.number="confidence" aria-label="置信水平"><option :value=".95">95% / Greenwood log-log</option><option :value=".9">90% / Greenwood log-log</option><option :value=".99">99% / Greenwood log-log</option></select></label><div class="protocol-line"><span>时间单位</span><b>小时 / h</b><span>在险表</span><b>400 / 800 / 1200 h</b></div><p class="caption">中位耐久仅在曲线达到0.5时报告；未达到时保留“尚未达到”，不以最后观察时间代替。</p><button v-if="auth.user?.role!=='viewer'" class="primary" :disabled="a.busy.value">提交耐久研究 <ArrowRight :size="16"/></button><p v-else class="role-note">阅读者可以查看配置，创建研究需要研究员权限。</p></form><aside class="method-note"><span class="eyebrow">METHOD NOTE / 01</span><h2>读曲线前的三件事</h2><ol><li><b>右删失不是失效</b><p>观察截止只说明试件至少工作了这段时间，之后未知。</p></li><li><b>区间是逐点的</b><p>Greenwood log-log保持边界在0到1内，尾部仍可能信息不足。</p></li><li><b>差异不是因果</b><p>log-rank比较分布，需独立试件与非信息性删失，不能替代工艺验证。</p></li></ol></aside></div></div></template>
